algorithms.pseudocode:
procedure CERTIFY(base b, step table T):
    offenders <- empty list
    for x in 0 .. b-1:
        for y in 0 .. b-1:
            for c in {0, 1}:                      # the reachable triples
                (d_true, c_true) <- ((x+y+c) mod b, floor((x+y+c)/b))
                if T[(x,y,c)] != (d_true, c_true):
                    append (x,y,c) to offenders
    if offenders is empty:
        return CERTIFIED  # correct at EVERY depth, by local-to-global transfer
    else:
        return REJECTED with offenders

procedure CONFIRM(base b, certified table T, depths D, trials t):
    for n in D:
        repeat t times:
            draw digit streams a, b of length n uniformly
            (digits, carry) <- UNROLL(T, a, b)      # carry starts at 0
            assert value(digits) + carry * b^n == value(a) + value(b)
    return all assertions held
